# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">AKABE GÖRÜŞMELERİ VE MEDİNE\'DE İSLAM\'IN YAYILIŞI (620 - 622)</text>\n  <rect x="20" y="45" width="210" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. İLK AKABE TEMASI (620)</text>\n  <text x="32" y="92" font-size="10.5" fill="#1e3a8a">• Nübüvvetin 11. yılı hac mevsimi</text>\n  <text x="32" y="114" font-size="10.5" fill="#1e3a8a">• Yesrib\'den (Medine) gelen</text>\n  <text x="32" y="132" font-size="10.5" font-weight="bold" fill="#1d4ed8">  6 kişilik Hazrec heyeti</text>\n  <text x="32" y="154" font-size="10.5" fill="#1e3a8a">• Evs ve Hazrec arasındaki Buâs</text>\n  <text x="32" y="172" font-size="10.5" fill="#1e3a8a">  savaşlarını bitirme arzusu</text>\n  <text x="32" y="196" font-size="10.5" font-weight="bold" fill="#1e40af">• Yesrib\'de İslam\'ın ilk tohumu</text>\n\n  <rect x="245" y="45" width="210" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">2. I. AKABE BİATI (621)</text>\n  <text x="257" y="92" font-size="10.5" fill="#14532d">• 10 Hazrec + 2 Evs = 12 kişi</text>\n  <text x="257" y="114" font-size="10.5" fill="#14532d">• Şirk koşmama, hırsızlık, zina ve</text>\n  <text x="257" y="132" font-size="10.5" fill="#14532d">  iftiradan kaçınma sözü</text>\n  <text x="257" y="154" font-size="10.5" font-weight="bold" fill="#15803d">• Mus\'ab bin Umeyr (r.a.)</text>\n  <text x="257" y="172" font-size="10.5" fill="#14532d">  İslam\'ın ilk öğretmeni olarak</text>\n  <text x="257" y="190" font-size="10.5" fill="#14532d">  Medine\'ye görevlendirildi</text>\n\n  <rect x="470" y="45" width="210" height="175" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">3. II. AKABE BİATI (622)</text>\n  <text x="482" y="92" font-size="10.5" fill="#78350f">• 73 erkek + 2 kadın = 75 kişi</text>\n  <text x="482" y="114" font-size="10.5" fill="#78350f">• Hz. Peygamber\'i canları ve</text>\n  <text x="482" y="132" font-size="10.5" fill="#78350f">  malları pahasına koruma sözü</text>\n  <text x="482" y="154" font-size="10.5" font-weight="bold" fill="#b45309">• 12 Nakîb (temsilci) seçimi</text>\n  <text x="482" y="172" font-size="10.5" fill="#78350f">• Hicret için hukuki ve siyasi</text>\n  <text x="482" y="190" font-size="10.5" fill="#78350f">  güven ortamı kuruldu</text>\n</svg>', '<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">SAHABİLERİN GÖÇÜ, DÂRÜNNEDVE KARARI VE HİCRETE ÇIKIŞ (622)</text>\n  <rect x="20" y="45" width="320" height="175" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#b91c1c">DÂRÜNNEDVE SUİKAST PLANI</text>\n  <text x="34" y="94" font-size="10.5" fill="#7f1d1d">• Sahabilerin Medine\'ye göç etmesiyle</text>\n  <text x="34" y="112" font-size="10.5" fill="#7f1d1d">  endişelenen Kureyş ileri gelenleri toplandı</text>\n  <text x="34" y="136" font-size="10.5" fill="#7f1d1d">• Hapis ve sürgün fikirleri reddedildi</text>\n  <text x="34" y="160" font-size="10.5" font-weight="bold" fill="#991b1b">• Ebû Cehil\'in teklifi: Her kabileden birer</text>\n  <text x="34" y="178" font-size="10.5" font-weight="bold" fill="#991b1b">  genç seçilerek ortak suikast düzenlenmesi</text>\n  <text x="34" y="200" font-size="10.5" fill="#7f1d1d">• Amaç: Kan davasını kabilelere dağıtmak</text>\n\n  <rect x="360" y="45" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">İLAHİ İZİN, EMANET VE HİCRET</text>\n  <text x="374" y="94" font-size="10.5" fill="#14532d">• Cebrâil (a.s.) planı Peygamberimize bildirdi</text>\n  <text x="374" y="118" font-size="10.5" font-weight="bold" fill="#15803d">• Hz. Ali (r.a.): Emanetleri sahiplerine</text>\n  <text x="374" y="136" font-size="10.5" fill="#14532d">  iade etmek üzere Mekke\'de bırakıldı</text>\n  <text x="374" y="160" font-size="10.5" font-weight="bold" fill="#15803d">• Hz. Ebû Bekir (r.a.): Hicret yol arkadaşı</text>\n  <text x="374" y="182" font-size="10.5" fill="#14532d">• Sevr Mağarası\'nda üç gün gizlenme ve</text>\n  <text x="374" y="200" font-size="10.5" fill="#14532d">  Medine-i Münevvere\'ye kutlu yürüyüş</text>\n</svg>', '<svg viewBox="0 0 700 240" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="240" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">MEKKE DÖNEMİ (571 / 610 - 622) GENEL KRONOLOJİSİ</text>\n  <rect x="20" y="45" width="210" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e40af">NÜBÜVVET ÖNCESİ (571-610)</text>\n  <text x="32" y="92" font-size="10.5" fill="#1e3a8a">• 571: Fil Olayı ve Kutlu Doğum</text>\n  <text x="32" y="114" font-size="10.5" fill="#1e3a8a">• Sütanne Halîme, Âmine, Dede</text>\n  <text x="32" y="132" font-size="10.5" fill="#1e3a8a">  Abdülmuttalib ve Ebû Tâlib</text>\n  <text x="32" y="154" font-size="10.5" fill="#1e3a8a">• Hilfü\'l-Fudûl (Erdemliler</text>\n  <text x="32" y="172" font-size="10.5" fill="#1e3a8a">  Cemiyeti) ve Hz. Hatice evliliği</text>\n  <text x="32" y="196" font-size="10.5" font-weight="bold" fill="#1d4ed8">• Kâbe Hakemliği (Muhammedü\'l-Emîn)</text>\n\n  <rect x="245" y="45" width="210" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#7e22ce">İLK VAHİY VE DAVET (610-616)</text>\n  <text x="257" y="92" font-size="10.5" fill="#581c87">• 610 Hira: İlk vahiy (Alak 1-5)</text>\n  <text x="257" y="114" font-size="10.5" fill="#581c87">• 3 yıl ferdi davet ve Dârülerkam</text>\n  <text x="257" y="136" font-size="10.5" fill="#581c87">• Safâ Tepesi açık davet</text>\n  <text x="257" y="158" font-size="10.5" fill="#581c87">• 615-616: Habeşistan Hicretleri</text>\n  <text x="257" y="180" font-size="10.5" font-weight="bold" fill="#7e22ce">• Hz. Hamza ve Hz. Ömer\'in</text>\n  <text x="257" y="198" font-size="10.5" font-weight="bold" fill="#7e22ce">  Müslüman olması</text>\n\n  <rect x="470" y="45" width="210" height="175" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#b45309">BOYKOT VE HİCRET (616-622)</text>\n  <text x="482" y="92" font-size="10.5" fill="#78350f">• 616-619: Şi\'b-i Ebî Tâlib Boykotu</text>\n  <text x="482" y="114" font-size="10.5" fill="#78350f">• 619-620: Hüzün Yılı ve Tâif</text>\n  <text x="482" y="136" font-size="10.5" fill="#78350f">• İsrâ ve Miraç Mucizesi</text>\n  <text x="482" y="158" font-size="10.5" fill="#78350f">• 620-622: Akabe Görüşmeleri</text>\n  <text x="482" y="180" font-size="10.5" font-weight="bold" fill="#b45309">• 622: Dârünnedve planı ve</text>\n  <text x="482" y="198" font-size="10.5" font-weight="bold" fill="#b45309">  Medine\'ye Hicret</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
